import math
class Shape:
    name = "Shape"
    def area(self):
        return 0
    def describe(self):
        return f"{self.name} with area {round(self.area(), 2)}"
class Rectangle(Shape):
    name = "Rectangle"
    def __init__(self, w, h):
        self.w, self.h = w, h
    def area(self):
        return self.w * self.h
class Square(Rectangle):
    name = "Square"
    def __init__(self, side):
        super().__init__(side, side)
class Circle(Shape):
    name = "Circle"
    def __init__(self, r):
        self.r = r
    def area(self):
        return math.pi * (self.r ** 2)
def total_area(shapes):
    return round(sum(s.area() for s in shapes), 2)

